# Developer wants to find all smart speakers that can make calls
result1 = CommunicationController.find_call_device(data, device_name="speaker")
# Returns only devices that support the "make_call" API

# Later, the developer wants to find all communication-capable devices including messaging
result2 = CommunicationController.find_communication_device(data, device_name="speaker")
# Returns a broader set of devices that support any communication feature

# Developer expects consistent behavior but gets different results
print(f"Call devices: {len(json.loads(result1)['devices'])}")  # Might show 2 devices
print(f"Communication devices: {len(json.loads(result2)['devices'])}")  # Might show 5 devices

